package fixture

import (
    "encoding/json"
    "net/http"
    "strconv"
)

type Item struct {
    ID int `json:"id"`
    Kind string `json:"kind"`
}

func Handler(items []Item) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        offset, limit := 0, -1
        for _, name := range []string{"offset", "limit"} {
            if raw, exists := r.URL.Query()[name]; exists {
                value, err := strconv.Atoi(raw[0])
                if err != nil || value < 0 {
                    http.Error(w, "invalid pagination", http.StatusBadRequest)
                    return
                }
                if name == "offset" { offset = value } else { limit = value }
            }
        }
        selected := make([]Item, 0)
        kind := r.URL.Query().Get("kind")
        for _, item := range items {
            if kind == "" || item.Kind == kind { selected = append(selected, item) }
        }
        if offset > len(selected) { offset = len(selected) }
        selected = selected[offset:]
        if limit >= 0 && limit < len(selected) { selected = selected[:limit] }
        w.Header().Set("Content-Type", "application/json")
        json.NewEncoder(w).Encode(selected)
    })
}

