package fixture_test

import (
    "encoding/json"
    "net/http/httptest"
    "reflect"
    "testing"
    f "fixture"
)

func TestHandlerContract(t *testing.T) {
    items := []f.Item{{9,"red"},{2,"blue"},{7,"red"},{4,"blue"},{1,"red"}}
    original := append([]f.Item(nil), items...)
    h := f.Handler(items)
    for _, tc := range []struct { query string; ids []int; status int }{
        {"", []int{9,2,7,4,1}, 200},
        {"?kind=red", []int{9,7,1}, 200},
        {"?kind=blue&offset=1&limit=1", []int{4}, 200},
        {"?kind=red&offset=1&limit=1", []int{7}, 200},
        {"?offset=2&limit=2", []int{7,4}, 200},
        {"?kind=missing", []int{}, 200},
        {"?kind=red&offset=3", []int{}, 200},
        {"?offset=999999&limit=2", []int{}, 200},
        {"?limit=0", []int{}, 200},
        {"?offset=-1", nil, 400}, {"?limit=-1", nil, 400},
        {"?offset=no", nil, 400}, {"?limit=", nil, 400},
        {"?limit=999999999999999999999999999", nil, 400},
        {"?unused=value", []int{9,2,7,4,1}, 200},
    } {
        w := httptest.NewRecorder()
        h.ServeHTTP(w, httptest.NewRequest("GET", "/"+tc.query, nil))
        if w.Code != tc.status { t.Fatalf("%s: status %d", tc.query, w.Code) }
        if tc.status != 200 { continue }
        if w.Header().Get("Content-Type") != "application/json" { t.Fatal("content type") }
        var got []f.Item
        if err := json.Unmarshal(w.Body.Bytes(), &got); err != nil { t.Fatal(err) }
        if got == nil { t.Fatal("empty result must be []") }
        ids := make([]int,0,len(got))
        for _, item := range got { ids=append(ids,item.ID) }
        if !reflect.DeepEqual(ids, tc.ids) { t.Fatalf("%s: got %v want %v",tc.query,ids,tc.ids) }
        if !reflect.DeepEqual(items, original) { t.Fatal("mutated caller items") }
    }
    w := httptest.NewRecorder()
    f.Handler(nil).ServeHTTP(w, httptest.NewRequest("GET", "/", nil))
    if w.Body.String() != "[]\n" { t.Fatalf("nil items: %s",w.Body.String()) }
}
